/**
 * STEPBible TVTMS versification source for @metaxia/scriptures-core.
 *
 * Loads the normalized mapping table (data/stepbible-versification/mapping.json)
 * generated by scripts/import.ts, and exposes a `VersificationSource` whose
 * `mapRef` routes an OT reference between the MT / LXX / English numbering
 * schemes. Only DIVERGENT verses are stored; anything absent from the table maps
 * to itself (identity) — EXCEPT for the reorder/divergent books on the MT<->LXX
 * pair, where a table-miss returns null rather than a known-wrong identity. An
 * entry explicitly set to `null` means "no equivalent in the target scheme".
 */
import { readFileSync } from 'fs';
import { fileURLToPath } from 'url';
import { dirname, join } from 'path';
import type { Scheme, Ref, VersificationSource } from '@metaxia/scriptures-core';

const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);
// dist/source.js -> ../data/stepbible-versification/mapping.json
const MAPPING_PATH = join(__dirname, '..', 'data', 'stepbible-versification', 'mapping.json');

/**
 * Books whose MT<->LXX numbering diverges by whole-block reorder / Greek
 * additions. Mirrors core's MT_LXX_DIVERGENT_BOOKS. For these, a MT<->LXX
 * table-miss returns null (refuse) rather than a confident-wrong identity.
 */
const MT_LXX_DIVERGENT_BOOKS = new Set<string>([
  'Jeremiah', 'Exodus', '1 Kings', 'Joshua', 'Proverbs', 'Daniel', 'Esther',
]);

function isMtLxxPair(from: Scheme, to: Scheme): boolean {
  return (from === 'MT' || to === 'MT') && (from === 'LXX' || to === 'LXX');
}

interface MappingValue {
  chapter: number;
  verse: number;
  part?: string;
}
type PairTable = Record<string, MappingValue | null>;
type MappingFile = Record<string, PairTable>; // `${from}->${to}` -> table

let cache: MappingFile | null = null;

function loadMapping(): MappingFile {
  if (cache) return cache;
  cache = JSON.parse(readFileSync(MAPPING_PATH, 'utf-8')) as MappingFile;
  return cache;
}

export const sourceInfo: VersificationSource = {
  id: 'stepbible-versification',
  systems: ['MT', 'LXX', 'English'],
  priority: 10, // above core's built-in (0)
  metadata: {
    name: 'STEPBible TVTMS',
    license: 'CC BY 4.0',
    source: 'STEPBible.org / Tyndale House Cambridge',
    urls: ['https://github.com/STEPBible/STEPBible-Data'],
  },
  mapRef(book: string, chapter: number, verse: number, from: Scheme, to: Scheme): Ref | null {
    if (from === to) return { chapter, verse };
    const tables = loadMapping();
    const table = tables[`${from}->${to}`];
    if (!table) return { chapter, verse }; // unknown pair -> identity
    const key = `${book} ${chapter}:${verse}`;
    if (key in table) {
      const value = table[key];
      if (value === null) return null; // explicitly no equivalent
      return { chapter: value.chapter, verse: value.verse };
    }
    // Not in the table. For a reorder/divergent book on the MT<->LXX pair, refuse
    // rather than return a known-wrong identity for a verse we didn't map.
    if (isMtLxxPair(from, to) && MT_LXX_DIVERGENT_BOOKS.has(book)) return null;
    return { chapter, verse }; // otherwise identity
  },

  /**
   * Whether the MT<->LXX (or English<->) mapping for `book` is trustworthy at
   * verse granularity. False for the reorder/divergent books on the MT<->LXX
   * pair (whole-block reorders + Greek additions that TVTMS cannot express as a
   * clean 1:1); true otherwise.
   */
  isReliable(book: string, from: Scheme, to: Scheme): boolean {
    if (from === to) return true;
    if (isMtLxxPair(from, to) && MT_LXX_DIVERGENT_BOOKS.has(book)) return false;
    return true;
  },
};
